{"command":"python3 - << 'EOF'
import time, os, hashlib
from cryptography.hazmat.primitives import hashes

data = os.urandom(20000 * 1024)

def bench(name, fn, n=5):
    # warmup
    fn()
    t0 = time.perf_counter()
    for _ in range(n):
        fn()
    t = (time.perf_counter() - t0) / n
    print(f"{name}: {t*1000:.2f} ms")

def crypto():
    d = hashes.Hash(hashes.SHA256())
    d.update(data)
    return d.finalize()

def hl():
    return hashlib.sha256(data).digest()

def hl2():
    h = hashlib.sha256()
    h.update(data)
    return h.digest()

bench("cryptography", crypto)
bench("hashlib", hl)
bench("hashlib update", hl2)

# verify same
print("match", crypto() == hl())
EOF"}

