static inline uint32_t rotr(uint32_t x, int n){ return (x>>n)|(x<<(32-n)); }
static inline uint32_t ch(uint32_t x,uint32_t y,uint32_t z){return (x&y)^(~x&z);}
static inline uint32_t maj(uint32_t x,uint32_t y,uint32_t z){return (x&y)^(x&z)^(y&z);}
static inline uint32_t ep0(uint32_t x){return rotr(x,2)^rotr(x,13)^rotr(x,22);}
static inline uint32_t ep1(uint32_t x){return rotr(x,6)^rotr(x,11)^rotr(x,25);}
static inline uint32_t sig0(uint32_t x){return rotr(x,7)^rotr(x,18)^(x>>3);}
static inline uint32_t sig1(uint32_t x){return rotr(x,17)^rotr(x,19)^(x>>10);}

static void sha256_scalar_block(uint32_t state[8], const uint8_t block[64]) {
    uint32_t w[64];
    for (int i=0;i<16;i++) {
        w[i] = ((uint32_t)block[i*4]<<24)|((uint32_t)block[i*4+1]<<16)|((uint32_t)block[i*4+2]<<8)|block[i*4+3];
    }
    for (int i=16;i<64;i++) w[i]=sig1(w[i-2])+w[i-7]+sig0(w[i-15])+w[i-16];
    uint32_t a=state[0],b=state[1],c=state[2],d=state[3],e=state[4],f=state[5],g=state[6],h=state[7];
    for (int i=0;i<64;i++) {
        uint32_t t1=h+ep1(e)+ch(e,f,g)+K256[i]+w[i];
        uint32_t t2=ep0(a)+maj(a,b,c);
        h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;
    }
    state[0]+=a; state[1]+=b; state[2]+=c; state[3]+=d; state[4]+=e; state[5]+=f; state[6]+=g; state[7]+=h;
}

int main() {
    // test vector "abc"
    uint32_t state[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    uint8_t block[64] = {0};
    block[0]='a'; block[1]='b'; block[2]='c'; block[3]=0x80;
    // length 24 bits = 3 bytes
    block[63] = 24;
    sha256_process_x86(state, block, 64);
    printf("NI abc: ");
    for (int i=0;i<8;i++) printf("%08x", state[i]);
    printf("\nexpected ba7816bf8f01cfea414140de5dae2223b00361a396177a9cb410ff61f20015ad\n");

    uint32_t st2[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    sha256_scalar_block(st2, block);
    printf("SC abc: ");
    for (int i=0;i<8;i++) printf("%08x", st2[i]);
    printf("\n");

    // benchmark large buffer
    size_t n = 20*1024*1024;
    n = (n/64)*64;
    uint8_t *buf = malloc(n);
    memset(buf, 0x5a, n);
    uint32_t st[8];
    // warmup
    for (int r=0;r<2;r++) {
        st[0]=0x6a09e667;st[1]=0xbb67ae85;st[2]=0x3c6ef372;st[3]=0xa54ff53a;
        st[4]=0x510e527f;st[5]=0x9b05688c;st[6]=0x1f83d9ab;st[7]=0x5be0cd19;
        sha256_process_x86(st, buf, (uint32_t)n);
    }
    struct timespec t0,t1;
