// 4-way interleaved SHA-256 using AVX2, public-domain style
// Based on the well-known approach of processing 4 independent messages.
// For a single message we split into 4 chunks and hash them independently,
// then... wait, SHA-256 is not parallelizable that way for a single digest.
// This file instead benchmarks 4 independent hashes to see raw throughput,
// and also a single-stream AVX2 schedule version.

#include <immintrin.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

static const uint32_t K[64] = {
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
