    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

static inline uint32_t rotr(uint32_t x, int n){ return (x>>n)|(x<<(32-n)); }
static inline uint32_t Ch(uint32_t x,uint32_t y,uint32_t z){return (x&y)^(~x&z);}
static inline uint32_t Maj(uint32_t x,uint32_t y,uint32_t z){return (x&y)^(x&z)^(y&z);}
static inline uint32_t Ep0(uint32_t x){return rotr(x,2)^rotr(x,13)^rotr(x,22);}
static inline uint32_t Ep1(uint32_t x){return rotr(x,6)^rotr(x,11)^rotr(x,25);}
static inline uint32_t Sig0(uint32_t x){return rotr(x,7)^rotr(x,18)^(x>>3);}
static inline uint32_t Sig1(uint32_t x){return rotr(x,17)^rotr(x,19)^(x>>10);}

// scalar block
static void sha256_block(uint32_t st[8], const uint8_t block[64]) {
    uint32_t w[64];
    for (int i=0;i<16;i++)
        w[i] = ((uint32_t)block[i*4]<<24)|((uint32_t)block[i*4+1]<<16)|((uint32_t)block[i*4+2]<<8)|block[i*4+3];
    for (int i=16;i<64;i++) w[i]=Sig1(w[i-2])+w[i-7]+Sig0(w[i-15])+w[i-16];
    uint32_t a=st[0],b=st[1],c=st[2],d=st[3],e=st[4],f=st[5],g=st[6],h=st[7];
    for (int i=0;i<64;i++) {
        uint32_t t1=h+Ep1(e)+Ch(e,f,g)+K[i]+w[i];
        uint32_t t2=Ep0(a)+Maj(a,b,c);
        h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;
    }
    st[0]+=a; st[1]+=b; st[2]+=c; st[3]+=d; st[4]+=e; st[5]+=f; st[6]+=g; st[7]+=h;
}

// 4-way: process 4 independent blocks at once
static inline __m128i load_be4(const uint8_t *p0, const uint8_t *p1, const uint8_t *p2, const uint8_t *p3, int off) {
    // load one big-endian word from each stream
    uint32_t w0 = ((uint32_t)p0[off]<<24)|((uint32_t)p0[off+1]<<16)|((uint32_t)p0[off+2]<<8)|p0[off+3];
    uint32_t w1 = ((uint32_t)p1[off]<<24)|((uint32_t)p1[off+1]<<16)|((uint32_t)p1[off+2]<<8)|p1[off+3];
    uint32_t w2 = ((uint32_t)p2[off]<<24)|((uint32_t)p2[off+1]<<16)|((uint32_t)p2[off+2]<<8)|p2[off+3];
    uint32_t w3 = ((uint32_t)p3[off]<<24)|((uint32_t)p3[off+1]<<16)|((uint32_t)p3[off+2]<<8)|p3[off+3];
    return _mm_set_epi32(w3,w2,w1,w0);
}
static inline __m128i rotr_v(__m128i x, int n) {
    return _mm_or_si128(_mm_srli_epi32(x, n), _mm_slli_epi32(x, 32-n));
}
static inline __m128i add4(__m128i a,__m128i b,__m128i c,__m128i d){
    return _mm_add_epi32(_mm_add_epi32(a,b), _mm_add_epi32(c,d));
}

static void sha256_4way(uint32_t st[4][8], const uint8_t *p[4]) {
    __m128i w[64];
    for (int i=0;i<16;i++)
