    for(int i=0;i<4;i++){A[i]=st[i][0];B[i]=st[i][1];C[i]=st[i][2];D[i]=st[i][3];E[i]=st[i][4];F[i]=st[i][5];G[i]=st[i][6];H[i]=st[i][7];}
    a=_mm_loadu_si128((__m128i*)A); b=_mm_loadu_si128((__m128i*)B);
    c=_mm_loadu_si128((__m128i*)C); d=_mm_loadu_si128((__m128i*)D);
    e=_mm_loadu_si128((__m128i*)E); f=_mm_loadu_si128((__m128i*)F);
    g=_mm_loadu_si128((__m128i*)G); h=_mm_loadu_si128((__m128i*)H);

    for (int i=0;i<64;i++) {
        __m128i S1 = _mm_xor_si128(rotr_v(e,6), _mm_xor_si128(rotr_v(e,11), rotr_v(e,25)));
