        // We'll redo store correctly below by keeping originals. This path is wrong; see fix in caller.
    }
    // store via extracting - redo additions from original st
    uint32_t na[4],nb[4],nc[4],nd[4],ne[4],nf[4],ng[4],nh[4];
    _mm_storeu_si128((__m128i*)na, a);
    _mm_storeu_si128((__m128i*)nb, b);
    _mm_storeu_si128((__m128i*)nc, c);
    _mm_storeu_si128((__m128i*)nd, d);
    _mm_storeu_si128((__m128i*)ne, e);
    _mm_storeu_si128((__m128i*)nf, f);
    _mm_storeu_si128((__m128i*)ng, g);
    _mm_storeu_si128((__m128i*)nh, h);
