    }
}

static double now() {
    struct timespec t; clock_gettime(CLOCK_MONOTONIC, &t);
    return t.tv_sec + t.tv_nsec*1e-9;
}

int main() {
    size_t n = 20*1024*1024;
    n = (n/64)*64;
    uint8_t *buf = aligned_alloc(64, n);
    memset(buf, 0x5a, n);

