#include <immintrin.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

// Single-stream SHA-256 with SSSE3 message schedule (bswap + vector W) and scalar rounds.
// Goal: beat OpenSSL's ~500 MB/s (40ms / 20MB).

static const uint32_t K[64] __attribute__((aligned(64))) = {
    0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
