    0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,
    0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,
    0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2
};

#define ROTR(x,n) (((x)>>(n))|((x)<<(32-(n))))
#define CH(x,y,z) (((x)&(y))^(~(x)&(z)))
#define MAJ(x,y,z) (((x)&(y))^((x)&(z))^((y)&(z)))
#define EP0(x) (ROTR(x,2)^ROTR(x,13)^ROTR(x,22))
#define EP1(x) (ROTR(x,6)^ROTR(x,11)^ROTR(x,25))
#define SIG0(x) (ROTR(x,7)^ROTR(x,18)^((x)>>3))
#define SIG1(x) (ROTR(x,17)^ROTR(x,19)^((x)>>10))

#define ROUND(a,b,c,d,e,f,g,h,i) do { \
    uint32_t t1 = (h) + EP1(e) + CH(e,f,g) + K[i] + w[i]; \
    uint32_t t2 = EP0(a) + MAJ(a,b,c); \
    (h)=g; (g)=f; (f)=e; (e)=(d)+t1; (d)=c; (c)=b; (b)=a; (a)=t1+t2; \
} while(0)

// SSSE3 byte swap shuffle
static void sha256_blocks(uint32_t state[8], const uint8_t *data, size_t nblocks) {
    const __m128i shuf = _mm_set_epi8(12,13,14,15, 8,9,10,11, 4,5,6,7, 0,1,2,3);
    uint32_t a=state[0],b=state[1],c=state[2],d=state[3],e=state[4],f=state[5],g=state[6],h=state[7];
    // We'll reset a..h each block from state
    for (size_t blk=0; blk<nblocks; blk++) {
        a=state[0]; b=state[1]; c=state[2]; d=state[3];
        e=state[4]; f=state[5]; g=state[6]; h=state[7];
