        __m128i x1 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(data+16)), shuf);
        __m128i x2 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(data+32)), shuf);
        __m128i x3 = _mm_shuffle_epi8(_mm_loadu_si128((const __m128i*)(data+48)), shuf);
        _mm_storeu_si128((__m128i*)(w+0), x0);
        _mm_storeu_si128((__m128i*)(w+4), x1);
        _mm_storeu_si128((__m128i*)(w+8), x2);
        _mm_storeu_si128((__m128i*)(w+12), x3);
