#include <OpenCL/opencl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <CommonCrypto/CommonDigest.h>

static double now(){struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return t.tv_sec+t.tv_nsec*1e-9;}

static const char *SRC = 
"__constant uint K[64] = {\n"
"0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,\n"
"0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,\n"
"0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,\n"
"0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,\n"
"0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,\n"
"0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,\n"
"0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,\n"
"0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2\n"
"};\n"
"#define ROTR(x,n) (((x)>>(n))|((x)<<(32-(n))))\n"
"#define CH(x,y,z) (((x)&(y))^(~(x)&(z)))\n"
"#define MAJ(x,y,z) (((x)&(y))^((x)&(z))^((y)&(z)))\n"
"#define EP0(x) (ROTR(x,2)^ROTR(x,13)^ROTR(x,22))\n"
"#define EP1(x) (ROTR(x,6)^ROTR(x,11)^ROTR(x,25))\n"
"#define SIG0(x) (ROTR(x,7)^ROTR(x,18)^((x)>>3))\n"
"#define SIG1(x) (ROTR(x,17)^ROTR(x,19)^((x)>>10))\n"
"__kernel void sha256_blocks(__global const uchar *data, __global uint *out, uint nblocks) {\n"
"  uint gid = get_global_id(0);\n"
"  if (gid >= nblocks) return;\n"
"  __global const uchar *blk = data + (size_t)gid * 64;\n"
"  uint w[64];\n"
"  for (int i=0;i<16;i++) {\n"
"    w[i] = ((uint)blk[i*4]<<24)|((uint)blk[i*4+1]<<16)|((uint)blk[i*4+2]<<8)|blk[i*4+3];\n"
"  }\n"
"  for (int i=16;i<64;i++) w[i]=SIG1(w[i-2])+w[i-7]+SIG0(w[i-15])+w[i-16];\n"
"  uint a=0x6a09e667u,b=0xbb67ae85u,c=0x3c6ef372u,d=0xa54ff53au;\n"
"  uint e=0x510e527fu,f=0x9b05688cu,g=0x1f83d9abu,h=0x5be0cd19u;\n"
"  for (int i=0;i<64;i++) {\n"
"    uint t1 = h + EP1(e) + CH(e,f,g) + K[i] + w[i];\n"
"    uint t2 = EP0(a) + MAJ(a,b,c);\n"
"    h=g; g=f; f=e; e=d+t1; d=c; c=b; b=a; a=t1+t2;\n"
"  }\n"
"  a+=0x6a09e667u; b+=0xbb67ae85u; c+=0x3c6ef372u; d+=0xa54ff53au;\n"
"  e+=0x510e527fu; f+=0x9b05688cu; g+=0x1f83d9abu; h+=0x5be0cd19u;\n"
"  __global uint *o = out + gid*8;\n"
"  o[0]=a; o[1]=b; o[2]=c; o[3]=d; o[4]=e; o[5]=f; o[6]=g; o[7]=h;\n"
"}\n";

static void check(cl_int err, const char *what){
    if(err!=CL_SUCCESS){ fprintf(stderr, "%s failed: %d\n", what, err); exit(1); }
}

int main(){
    cl_platform_id plats[4]; cl_uint np=0;
    clGetPlatformIDs(4, plats, &np);
    cl_device_id devs[8]; cl_uint nd=0;
    clGetDeviceIDs(plats[0], CL_DEVICE_TYPE_GPU, 8, devs, &nd);
    // pick AMD (second GPU) if present, else last
    cl_device_id dev = devs[nd-1];
    char dname[256]={0};
    clGetDeviceInfo(dev, CL_DEVICE_NAME, 255, dname, NULL);
    printf("using %s\n", dname);

    cl_int err;
    cl_context ctx = clCreateContext(NULL, 1, &dev, NULL, NULL, &err); check(err,"ctx");
    cl_queue_properties props[] = {CL_QUEUE_PROPERTIES, CL_QUEUE_PROFILING_ENABLE, 0};
    cl_command_queue q = clCreateCommandQueueWithProperties(ctx, dev, props, &err); check(err,"queue");

    size_t srclen = strlen(SRC);
    cl_program prog = clCreateProgramWithSource(ctx, 1, &SRC, &srclen, &err); check(err,"prog");
    err = clBuildProgram(prog, 1, &dev, "-cl-fast-relaxed-math", NULL, NULL);
    if(err!=CL_SUCCESS){
        char log[8192]; size_t logsz=0;
        clGetProgramBuildInfo(prog, dev, CL_PROGRAM_BUILD_LOG, sizeof(log), log, &logsz);
        fprintf(stderr, "build log:\n%s\n", log);
        return 1;
    }
    cl_kernel kern = clCreateKernel(prog, "sha256_blocks", &err); check(err,"kern");

    size_t n = 20*1024*1024; n = (n/64)*64;
    uint32_t nblocks = (uint32_t)(n/64);
    uint8_t *buf = malloc(n);
    memset(buf, 0x5a, n);
    uint32_t *out = malloc((size_t)nblocks*32);

    cl_mem d_in = clCreateBuffer(ctx, CL_MEM_READ_ONLY, n, NULL, &err); check(err,"din");
    cl_mem d_out = clCreateBuffer(ctx, CL_MEM_WRITE_ONLY, (size_t)nblocks*32, NULL, &err); check(err,"dout");

    // warmup
    clEnqueueWriteBuffer(q, d_in, CL_TRUE, 0, n, buf, 0, NULL, NULL);
    clSetKernelArg(kern, 0, sizeof(cl_mem), &d_in);
    clSetKernelArg(kern, 1, sizeof(cl_mem), &d_out);
    clSetKernelArg(kern, 2, sizeof(uint32_t), &nblocks);
    size_t g = nblocks;
    clEnqueueNDRangeKernel(q, kern, 1, NULL, &g, NULL, 0, NULL, NULL);
    clFinish(q);

    int reps=5;
    double t0=now();
    for(int i=0;i<reps;i++){
        clEnqueueWriteBuffer(q, d_in, CL_FALSE, 0, n, buf, 0, NULL, NULL);
        clEnqueueNDRangeKernel(q, kern, 1, NULL, &g, NULL, 0, NULL, NULL);
        clEnqueueReadBuffer(q, d_out, CL_FALSE, 0, (size_t)nblocks*32, out, 0, NULL, NULL);
        clFinish(q);
    }
    double t1=now();
    printf("GPU independent blocks 20MB (incl transfer of 20MB in + 10MB out): %.2f ms\n", (t1-t0)/reps*1000);

    // compute only
    cl_event ev;
    t0=now();
    for(int i=0;i<reps;i++){
        clEnqueueNDRangeKernel(q, kern, 1, NULL, &g, NULL, 0, NULL, &ev);
        clFinish(q);
    }
    t1=now();
    printf("GPU compute only: %.2f ms\n", (t1-t0)/reps*1000);

    // verify one block against CommonCrypto? We hashed each block independently from IV.
    // Check block 0 by doing a manual comparison later in python; print first hash.
    printf("block0: ");
    for(int i=0;i<8;i++) printf("%08x", out[i]);
    printf("\n");

    // transfer only
    t0=now();
    for(int i=0;i<reps;i++){
        clEnqueueWriteBuffer(q, d_in, CL_TRUE, 0, n, buf, 0, NULL, NULL);
    }
    t1=now();
    printf("H2D 20MB: %.2f ms\n", (t1-t0)/reps*1000);

    return 0;
}
