{"command":"cd "$HOME/shatest2" && cat > sha_tree.c << 'EOF'
#include <OpenCL/opencl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

static double now(){struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return t.tv_sec+t.tv_nsec*1e-9;}
static void check(cl_int err, const char *what){ if(err!=CL_SUCCESS){ fprintf(stderr,"%s failed %d\n",what,err); exit(1);} }

/* Kernel 1: hash each 64-byte block independently from IV, write 32-byte digest (big-endian bytes).
   Kernel 2: hash pairs of 32-byte digests (as a 64-byte block) from IV, write 32-byte digest.
   We do this until one digest remains. That final digest is a tree hash, NOT standard SHA-256,
   but this measures whether a reduction is fast enough. For a correct SHA-256 we would need
   a sequential chain; this is only a timing experiment for the reduction cost. */

static const char *SRC =
"__constant uint K[64] = {\n"
"0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,\n"
"0xd807aa98,0x12835b01,0x243185be,0x550c7dc3,0x72be5d74,0x80deb1fe,0x9bdc06a7,0xc19bf174,\n"
"0xe49b69c1,0xefbe4786,0x0fc19dc6,0x240ca1cc,0x2de92c6f,0x4a7484aa,0x5cb0a9dc,0x76f988da,\n"
"0x983e5152,0xa831c66d,0xb00327c8,0xbf597fc7,0xc6e00bf3,0xd5a79147,0x06ca6351,0x14292967,\n"
"0x27b70a85,0x2e1b2138,0x4d2c6dfc,0x53380d13,0x650a7354,0x766a0abb,0x81c2c92e,0x92722c85,\n"
"0xa2bfe8a1,0xa81a664b,0xc24b8b70,0xc76c51a3,0xd192e819,0xd6990624,0xf40e3585,0x106aa070,\n"
"0x19a4c116,0x1e376c08,0x2748774c,0x34b0bcb5,0x391c0cb3,0x4ed8aa4a,0x5b9cca4f,0x682e6ff3,\n"
"0x748f82ee,0x78a5636f,0x84c87814,0x8cc70208,0x90befffa,0xa4506ceb,0xbef9a3f7,0xc67178f2};\n"
"#define ROTR(x,n) (((x)>>(n))|((x)<<(32-(n))))\n"
"#define CH(x,y,z) (((x)&(y))^(~(x)&(z)))\n"
"#define MAJ(x,y,z) (((x)&(y))^((x)&(z))^((y)&(z)))\n"
"#define EP0(x) (ROTR(x,2)^ROTR(x,13)^ROTR(x,22))\n"
"#define EP1(x) (ROTR(x,6)^ROTR(x,11)^ROTR(x,25))\n"
"#define SIG0(x) (ROTR(x,7)^ROTR(x,18)^((x)>>3))\n"
"#define SIG1(x) (ROTR(x,17)^ROTR(x,19)^((x)>>10))\n"
"void compress(const uchar blk[64], uint state[8]){\n"
"  uint w[64];\n"
"  for(int i=0;i<16;i++) w[i]=((uint)blk[i*4]<<24)|((uint)blk[i*4+1]<<16)|((uint)blk[i*4+2]<<8)|blk[i*4+3];\n"
"  for(int i=16;i<64;i++) w[i]=SIG1(w[i-2])+w[i-7]+SIG0(w[i-15])+w[i-16];\n"
"  uint a=state[0],b=state[1],c=state[2],d=state[3],e=state[4],f=state[5],g=state[6],h=state[7];\n"
"  for(int i=0;i<64;i++){ uint t1=h+EP1(e)+CH(e,f,g)+K[i]+w[i]; uint t2=EP0(a)+MAJ(a,b,c); h=g;g=f;f=e;e=d+t1;d=c;c=b;b=a;a=t1+t2; }\n"
"  state[0]+=a;state[1]+=b;state[2]+=c;state[3]+=d;state[4]+=e;state[5]+=f;state[6]+=g;state[7]+=h;\n"
"}\n"
"__kernel void level0(__global const uchar *data, __global uchar *out, uint nblocks){\n"
"  uint gid=get_global_id(0);\n"
"  if(gid>=nblocks) return;\n"
"  uint st[8]={0x6a09e667u,0xbb67ae85u,0x3c6ef372u,0xa54ff53au,0x510e527fu,0x9b05688cu,0x1f83d9abu,0x5be0cd19u};\n"
"  compress(data+(size_t)gid*64, st);\n"
"  __global uchar *o=out+(size_t)gid*32;\n"
"  for(int i=0;i<8;i++){ o[i*4]=(uchar)(st[i]>>24); o[i*4+1]=(uchar)(st[i]>>16); o[i*4+2]=(uchar)(st[i]>>8); o[i*4+3]=(uchar)st[i]; }\n"
"}\n"
"/* each work-item consumes CHUNK 32-byte nodes and hashes them sequentially as 64-byte blocks\n"
"   (two nodes per block). CHUNK must be even. Writes one 32-byte digest. */\n"
"__kernel void reduce(__global const uchar *in, __global uchar *out, uint groups, uint nodes_per_group){\n"
"  uint gid=get_global_id(0);\n"
"  if(gid>=groups) return;\n"
"  uint st[8]={0x6a09e667u,0xbb67ae85u,0x3c6ef372u,0xa54ff53au,0x510e527fu,0x9b05688cu,0x1f83d9abu,0x5be0cd19u};\n"
"  __global const uchar *base = in + (size_t)gid * nodes_per_group * 32;\n"
"  uchar blk[64];\n"
"  uint nblocks = nodes_per_group / 2;\n"
"  for(uint b=0;b<nblocks;b++){\n"
"    for(int i=0;i<64;i++) blk[i]=base[(size_t)b*64+i];\n"
"    compress(blk, st);\n"
"  }\n"
"  __global uchar *o=out+(size_t)gid*32;\n"
"  for(int i=0;i<8;i++){ o[i*4]=(uchar)(st[i]>>24); o[i*4+1]=(uchar)(st[i]>>16); o[i*4+2]=(uchar)(st[i]>>8); o[i*4+3]=(uchar)st[i]; }\n"
"}\n"
"/* Sequential chain of NBLOCKS blocks starting from IV. One work item. For timing the dependency chain. */\n"
"__kernel void chain(__global const uchar *data, __global uchar *out, uint nblocks){\n"
"  uint st[8]={0x6a09e667u,0xbb67ae85u,0x3c6ef372u,0xa54ff53au,0x510e527fu,0x9b05688cu,0x1f83d9abu,0x5be0cd19u};\n"
"  for(uint b=0;b<nblocks;b++){\n"
"    compress(data+(size_t)b*64, st);\n"
"  }\n"
"  for(int i=0;i<8;i++){ out[i*4]=(uchar)(st[i]>>24); out[i*4+1]=(uchar)(st[i]>>16); out[i*4+2]=(uchar)(st[i]>>8); out[i*4+3]=(uchar)st[i]; }\n"
"}\n"
"/* Many independent chains: each work-item chains CHAINLEN blocks. */\n"
"__kernel void chains(__global const uchar *data, __global uchar *out, uint chainlen, uint nchains){\n"
"  uint gid=get_global_id(0);\n"
