"}\n";

int main(){
    cl_platform_id plat; cl_uint np;
    clGetPlatformIDs(1,&plat,&np);
    cl_device_id devs[8]; cl_uint nd;
    clGetDeviceIDs(plat, CL_DEVICE_TYPE_GPU, 8, devs, &nd);
    cl_device_id dev=devs[nd-1];
    char name[128]={0}; clGetDeviceInfo(dev, CL_DEVICE_NAME, 127, name, NULL);
    printf("device %s\n", name);
    cl_int err;
    cl_context ctx=clCreateContext(NULL,1,&dev,NULL,NULL,&err); check(err,"ctx");
    cl_command_queue q=clCreateCommandQueue(ctx,dev,0,&err); check(err,"q");
    size_t sl=strlen(SRC);
    cl_program prog=clCreateProgramWithSource(ctx,1,&SRC,&sl,&err); check(err,"p");
    err=clBuildProgram(prog,1,&dev,"-cl-fast-relaxed-math",NULL,NULL);
    if(err){ char log[16384]; clGetProgramBuildInfo(prog,dev,CL_PROGRAM_BUILD_LOG,sizeof(log),log,NULL); fprintf(stderr,"%s\n",log); return 1; }
    cl_kernel k0=clCreateKernel(prog,"level0",&err);
    cl_kernel kr=clCreateKernel(prog,"reduce",&err);
    cl_kernel kc=clCreateKernel(prog,"chains",&err);

    size_t n=20*1024*1024; n=(n/64)*64;
    uint32_t nblocks=(uint32_t)(n/64); // 320000
    uint8_t *buf=malloc(n); memset(buf,0x5a,n);
    cl_mem d_in=clCreateBuffer(ctx, CL_MEM_READ_ONLY, n, NULL, &err);
    // output of level0: nblocks * 32
    cl_mem d_a=clCreateBuffer(ctx, CL_MEM_READ_WRITE, (size_t)nblocks*32, NULL, &err);
    cl_mem d_b=clCreateBuffer(ctx, CL_MEM_READ_WRITE, (size_t)nblocks*32, NULL, &err);

    clEnqueueWriteBuffer(q, d_in, CL_TRUE, 0, n, buf, 0, NULL, NULL);

    // time chains of various lengths
    for (uint32_t chainlen : (uint32_t[]){1,4,16,64,256,1024,4096}) {
        uint32_t nchains = nblocks / chainlen;
        clSetKernelArg(kc,0,sizeof(cl_mem),&d_in);
        clSetKernelArg(kc,1,sizeof(cl_mem),&d_a);
        clSetKernelArg(kc,2,sizeof(uint32_t),&chainlen);
        clSetKernelArg(kc,3,sizeof(uint32_t),&nchains);
        size_t g=nchains;
        // warmup
        clEnqueueNDRangeKernel(q,kc,1,NULL,&g,NULL,0,NULL,NULL); clFinish(q);
        double t0=now();
        int reps=3;
        for(int i=0;i<reps;i++){ clEnqueueNDRangeKernel(q,kc,1,NULL,&g,NULL,0,NULL,NULL); clFinish(q); }
        double ms=(now()-t0)/reps*1000;
        printf("chains len=%5u nchains=%7u  compute %.2f ms\n", chainlen, nchains, ms);
    }

    // full pipeline: H2D + level0 + a couple reductions + D2H 32 bytes
    clSetKernelArg(k0,0,sizeof(cl_mem),&d_in);
    clSetKernelArg(k0,1,sizeof(cl_mem),&d_a);
    clSetKernelArg(k0,2,sizeof(uint32_t),&nblocks);
    size_t g=nblocks;
    clEnqueueNDRangeKernel(q,k0,1,NULL,&g,NULL,0,NULL,NULL); clFinish(q);
    double t0=now(); int reps=3;
    uint8_t finald[32];
    for(int r=0;r<reps;r++){
        clEnqueueWriteBuffer(q, d_in, CL_FALSE, 0, n, buf, 0, NULL, NULL);
        clEnqueueNDRangeKernel(q,k0,1,NULL,&g,NULL,0,NULL,NULL);
        // reduce by factor 256 repeatedly: nodes_per_group=256 (128 blocks)
        cl_mem src=d_a, dst=d_b;
        uint32_t nodes=nblocks;
        while(nodes>1){
            uint32_t npg = nodes>256 ? 256 : nodes;
            // pad npg even
            if(npg%2) npg++;
            uint32_t groups = nodes / npg;
            uint32_t rem = nodes % npg;
            // for timing ignore remainder correctness
            if(groups==0){ groups=1; npg=nodes; if(npg%2) npg++; }
            clSetKernelArg(kr,0,sizeof(cl_mem),&src);
            clSetKernelArg(kr,1,sizeof(cl_mem),&dst);
            clSetKernelArg(kr,2,sizeof(uint32_t),&groups);
            clSetKernelArg(kr,3,sizeof(uint32_t),&npg);
            size_t gg=groups;
            clEnqueueNDRangeKernel(q,kr,1,NULL,&gg,NULL,0,NULL,NULL);
            nodes=groups;
            cl_mem tmp=src; src=dst; dst=tmp;
        }
        clEnqueueReadBuffer(q, src, CL_FALSE, 0, 32, finald, 0, NULL, NULL);
        clFinish(q);
    }
    printf("full tree pipeline: %.2f ms\n", (now()-t0)/reps*1000);
    printf("digest "); for(int i=0;i<32;i++) printf("%02x", finald[i]); printf("\n");
    return 0;
}
