// openssl's block function
extern void sha256_block_data_order(uint32_t *state, const uint8_t *data, size_t num);

static inline uint32_t rr(uint32_t x, int n){ return _rotr(x, n); }

__attribute__((noinline))
static void blocks_rorx(uint32_t st[8], const uint8_t *data, size_t nblocks){
    for(size_t b=0;b<nblocks;b++){
        uint32_t w[64];
        for(int i=0;i<16;i++){
            w[i] = (uint32_t)data[i*4]<<24 | (uint32_t)data[i*4+1]<<16 | (uint32_t)data[i*4+2]<<8 | data[i*4+3];
        }
        for(int i=16;i<64;i++){
            uint32_t x=w[i-2];
            uint32_t s1 = rr(x,17)^rr(x,19)^(x>>10);
            x=w[i-15];
            uint32_t s0 = rr(x,7)^rr(x,18)^(x>>3);
            w[i]=s1+w[i-7]+s0+w[i-16];
        }
        uint32_t a=st[0],b_=st[1],c=st[2],d=st[3],e=st[4],f=st[5],g=st[6],h=st[7];
        #pragma unroll
        for(int i=0;i<64;i++){
            uint32_t t1 = h + (rr(e,6)^rr(e,11)^rr(e,25)) + ((e&f)^(~e&g)) + K[i] + w[i];
            uint32_t t2 = (rr(a,2)^rr(a,13)^rr(a,22)) + ((a&b_)^(a&c)^(b_&c));
            h=g; g=f; f=e; e=d+t1; d=c; c=b_; b_=a; a=t1+t2;
        }
        st[0]+=a; st[1]+=b_; st[2]+=c; st[3]+=d; st[4]+=e; st[5]+=f; st[6]+=g; st[7]+=h;
        data+=64;
    }
}

static double now(){struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return t.tv_sec+t.tv_nsec*1e-9;}

int main(){
    size_t n=20*1024*1024; n=(n/64)*64;
    uint8_t *buf=aligned_alloc(64, n);
    memset(buf, 0x5a, n);
    uint32_t st[8]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    uint32_t st2[8]; memcpy(st2, st, 32);

    // openssl state is little-endian words of the big-endian hash state, same as ours
    double t0=now();
    sha256_block_data_order(st, buf, n/64);
    double t1=now();
    printf("openssl block: %.2f ms  ", (t1-t0)*1000);
    for(int i=0;i<8;i++) printf("%08x", st[i]); printf("\n");

    t0=now();
    blocks_rorx(st2, buf, n/64);
    t1=now();
