#define PY_SSIZE_T_CLEAN
#include <Python.h>
#include <stdint.h>
#include <string.h>
#include <openssl/sha.h>

extern void sha256_block_data_order(uint32_t *state, const uint8_t *data, size_t num);

static PyObject *sha256_fast(PyObject *self, PyObject *arg) {
    Py_buffer view;
    if (PyObject_GetBuffer(arg, &view, PyBUF_SIMPLE) != 0)
        return NULL;
    const uint8_t *data = (const uint8_t *)view.buf;
    Py_ssize_t len = view.len;

    uint32_t st[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
                      0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    size_t nblocks = (size_t)len / 64;
    size_t rem = (size_t)len % 64;
    if (nblocks)
        sha256_block_data_order(st, data, nblocks);

    uint8_t last[128];
    memset(last, 0, sizeof(last));
    if (rem)
        memcpy(last, data + nblocks * 64, rem);
    last[rem] = 0x80;
    uint64_t bits = (uint64_t)len * 8;
    size_t padblocks;
    if (rem < 56) {
        padblocks = 1;
    } else {
        padblocks = 2;
    }
    // length in last 8 bytes of the final block, big endian
    uint8_t *lenp = last + padblocks * 64 - 8;
    for (int i = 7; i >= 0; i--) {
        lenp[i] = (uint8_t)(bits & 0xff);
        bits >>= 8;
    }
    sha256_block_data_order(st, last, padblocks);

    uint8_t out[32];
    for (int i = 0; i < 8; i++) {
        out[i*4]   = (uint8_t)(st[i] >> 24);
        out[i*4+1] = (uint8_t)(st[i] >> 16);
        out[i*4+2] = (uint8_t)(st[i] >> 8);
        out[i*4+3] = (uint8_t)(st[i]);
    }
    PyBuffer_Release(&view);
    return PyBytes_FromStringAndSize((char *)out, 32);
}

static PyMethodDef methods[] = {
    {"sha256", sha256_fast, METH_O, NULL},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef module = {PyModuleDef_HEAD_INIT, "fastsha", NULL, -1, methods};
PyMODINIT_FUNC PyInit_fastsha(void) { return PyModule_Create(&module); }
