// Each work-item processes CHAINLEN consecutive blocks starting from IV (independent chains).
// We also test a "carry" kernel: given an array of states (one per chain) and the next
// segment, continue. To simulate dependency we'd have to run them serially.
// Here we only time many parallel short chains of various lengths, plus H2D.

static const char *SRC = R"CL(
__constant uint K[64] = {
0x428a2f98,0x71374491,0xb5c0fbcf,0xe9b5dba5,0x3956c25b,0x59f111f1,0x923f82a4,0xab1c5ed5,
