    uint t2=EP0(a)+MAJ(a,b,c);
    h=g;g=f;f=e;e=d+t1;d=c;c=b;b=a;a=t1+t2;
  }
  state[0]+=a;state[1]+=b;state[2]+=c;state[3]+=d;state[4]+=e;state[5]+=f;state[6]+=g;state[7]+=h;
}
__kernel void chains(__global const uchar *data, __global uint *out, uint chainlen, uint nchains){
  uint gid=get_global_id(0);
  if(gid>=nchains) return;
  uint st[8]={0x6a09e667u,0xbb67ae85u,0x3c6ef372u,0xa54ff53au,0x510e527fu,0x9b05688cu,0x1f83d9abu,0x5be0cd19u};
  __global const uchar *base=data+(size_t)gid*chainlen*64;
  for(uint b=0;b<chainlen;b++) compress(base+(size_t)b*64, st);
  __global uint *o=out+gid*8;
  for(int i=0;i<8;i++) o[i]=st[i];
}
)CL";

int main(){
    cl_platform_id plat; cl_uint np; clGetPlatformIDs(1,&plat,&np);
    cl_device_id devs[8]; cl_uint nd; clGetDeviceIDs(plat, CL_DEVICE_TYPE_GPU, 8, devs, &nd);
    cl_device_id dev=devs[nd-1];
    char name[128]={0}; clGetDeviceInfo(dev, CL_DEVICE_NAME, 127, name, NULL);
    printf("dev %s\n", name);
    cl_int err;
    cl_context ctx=clCreateContext(NULL,1,&dev,NULL,NULL,&err); ck(err,"ctx");
    cl_command_queue q=clCreateCommandQueue(ctx,dev,0,&err); ck(err,"q");
    const char *src=SRC; size_t sl=strlen(src);
    cl_program prog=clCreateProgramWithSource(ctx,1,&src,&sl,&err); ck(err,"prog");
    err=clBuildProgram(prog,1,&dev,"-cl-fast-relaxed-math -cl-mad-enable",NULL,NULL);
    if(err){ char log[20000]; clGetProgramBuildInfo(prog,dev,CL_PROGRAM_BUILD_LOG,sizeof(log),log,NULL); fprintf(stderr,"%s\n",log); return 1; }
    cl_kernel k=clCreateKernel(prog,"chains",&err); ck(err,"k");

    size_t n=20*1024*1024; n=(n/64)*64;
    uint32_t nblocks=n/64;
    uint8_t *buf=(uint8_t*)malloc(n); memset(buf,0x5a,n);
    cl_mem d_in=clCreateBuffer(ctx, CL_MEM_READ_ONLY|CL_MEM_COPY_HOST_PTR, n, buf, &err);
    cl_mem d_out=clCreateBuffer(ctx, CL_MEM_WRITE_ONLY, (size_t)nblocks*32, NULL, &err);

    uint32_t lens[]={1,2,4,8,16,32,64,128,256};
    for(uint32_t chainlen: lens){
        uint32_t nchains=nblocks/chainlen;
        clSetKernelArg(k,0,sizeof(cl_mem),&d_in);
        clSetKernelArg(k,1,sizeof(cl_mem),&d_out);
        clSetKernelArg(k,2,sizeof(uint32_t),&chainlen);
        clSetKernelArg(k,3,sizeof(uint32_t),&nchains);
        size_t g=nchains;
        size_t local=64;
        if(g<local) local=0;
        clEnqueueNDRangeKernel(q,k,1,NULL,&g, local?&local:NULL,0,NULL,NULL); clFinish(q);
        double t0=now(); int reps=3;
        for(int i=0;i<reps;i++){ clEnqueueNDRangeKernel(q,k,1,NULL,&g,local?&local:NULL,0,NULL,NULL); clFinish(q); }
        printf("chainlen %4u nchains %7u  %.2f ms\n", chainlen, nchains, (now()-t0)/reps*1000);
    }
    // H2D + best chain + tiny read
    uint32_t chainlen=8, nchains=nblocks/chainlen;
    clSetKernelArg(k,2,sizeof(uint32_t),&chainlen);
    clSetKernelArg(k,3,sizeof(uint32_t),&nchains);
    size_t g=nchains, local=64;
    uint32_t hostout[8];
    double t0=now(); int reps=3;
    for(int i=0;i<reps;i++){
        clEnqueueWriteBuffer(q,d_in,CL_FALSE,0,n,buf,0,NULL,NULL);
        clEnqueueNDRangeKernel(q,k,1,NULL,&g,&local,0,NULL,NULL);
        clEnqueueReadBuffer(q,d_out,CL_FALSE,0,32,hostout,0,NULL,NULL);
        clFinish(q);
    }
    printf("H2D+chain8+read32: %.2f ms\n", (now()-t0)/reps*1000);
    return 0;
}
