#include <cstring>
#include <ctime>
static double now(){timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return t.tv_sec+t.tv_nsec*1e-9;}
static void ck(cl_int e,const char*w){if(e){fprintf(stderr,"%s %d\n",w,e); exit(1);}}
int main(){
    FILE *f=fopen("k.cl","r"); fseek(f,0,SEEK_END); long sz=ftell(f); fseek(f,0,SEEK_SET);
    char *src=(char*)malloc(sz+1); fread(src,1,sz,f); src[sz]=0; fclose(f);
    cl_platform_id plat; cl_uint np; clGetPlatformIDs(1,&plat,&np);
    cl_device_id devs[8]; cl_uint nd; clGetDeviceIDs(plat, CL_DEVICE_TYPE_GPU, 8, devs, &nd);
    cl_device_id dev=devs[nd-1];
    cl_int err;
    cl_context ctx=clCreateContext(NULL,1,&dev,NULL,NULL,&err); ck(err,"ctx");
    cl_command_queue q=clCreateCommandQueue(ctx,dev,0,&err); ck(err,"q");
    size_t sl=strlen(src);
    cl_program prog=clCreateProgramWithSource(ctx,1,(const char**)&src,&sl,&err);
    err=clBuildProgram(prog,1,&dev,"-cl-fast-relaxed-math",NULL,NULL);
    if(err){ char log[8000]; clGetProgramBuildInfo(prog,dev,CL_PROGRAM_BUILD_LOG,sizeof(log),log,NULL); fprintf(stderr,"%s\n",log); return 1; }
    cl_kernel k=clCreateKernel(prog,"chains",&err);

    // verify chainlen=1 and chainlen=4 against CPU
    size_t nblocks=64;
    size_t n=nblocks*64;
    uint8_t *buf=(uint8_t*)malloc(n);
    for(size_t i=0;i<n;i++) buf[i]=(uint8_t)(i*17+3);
    cl_mem d_in=clCreateBuffer(ctx, CL_MEM_READ_ONLY|CL_MEM_COPY_HOST_PTR, n, buf, &err);
    cl_mem d_out=clCreateBuffer(ctx, CL_MEM_WRITE_ONLY, nblocks*32, NULL, &err);

    for (uint32_t chainlen : {1u, 4u, 16u}) {
        uint32_t nchains=nblocks/chainlen;
        clSetKernelArg(k,0,sizeof(cl_mem),&d_in);
        clSetKernelArg(k,1,sizeof(cl_mem),&d_out);
        clSetKernelArg(k,2,sizeof(uint32_t),&chainlen);
        clSetKernelArg(k,3,sizeof(uint32_t),&nchains);
        size_t g=nchains;
        clEnqueueNDRangeKernel(q,k,1,NULL,&g,NULL,0,NULL,NULL);
        uint32_t *host=(uint32_t*)malloc(nchains*32);
        clEnqueueReadBuffer(q,d_out,CL_TRUE,0,nchains*32,host,0,NULL,NULL);
        int bad=0;
        for(uint32_t c=0;c<nchains;c++){
            uint32_t st[8]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
            // use openssl block
            extern void sha256_block_data_order(uint32_t*, const uint8_t*, size_t);
            sha256_block_data_order(st, buf+c*chainlen*64, chainlen);
            for(int i=0;i<8;i++) if(st[i]!=host[c*8+i]) bad++;
            if(c==0){
                printf("chainlen %u cpu ", chainlen); for(int i=0;i<8;i++) printf("%08x", st[i]); printf("\n");
                printf("chainlen %u gpu ", chainlen); for(int i=0;i<8;i++) printf("%08x", host[i]); printf("\n");
            }
        }
        printf("chainlen %u mismatches %d / %u\n", chainlen, bad, nchains);
        free(host);
    }

    // time ONE chain of 20MB on GPU (single work item)
    size_t big=20*1024*1024; big=(big/64)*64;
    uint8_t *bb=(uint8_t*)malloc(big); memset(bb,0x5a,big);
    cl_mem din2=clCreateBuffer(ctx, CL_MEM_READ_ONLY, big, NULL, &err);
    cl_mem dout2=clCreateBuffer(ctx, CL_MEM_WRITE_ONLY, 32, NULL, &err);
    clEnqueueWriteBuffer(q,din2,CL_TRUE,0,big,bb,0,NULL,NULL);
    uint32_t chainlen=(uint32_t)(big/64), nchains=1;
    clSetKernelArg(k,0,sizeof(cl_mem),&din2);
    clSetKernelArg(k,1,sizeof(cl_mem),&dout2);
    clSetKernelArg(k,2,sizeof(uint32_t),&chainlen);
    clSetKernelArg(k,3,sizeof(uint32_t),&nchains);
    size_t g=1;
    clEnqueueNDRangeKernel(q,k,1,NULL,&g,NULL,0,NULL,NULL); clFinish(q);
    double t0=now();
    clEnqueueNDRangeKernel(q,k,1,NULL,&g,NULL,0,NULL,NULL); clFinish(q);
    printf("single GPU chain 20MB: %.2f ms\n", (now()-t0)*1000);
    uint32_t hout[8];
    clEnqueueReadBuffer(q,dout2,CL_TRUE,0,32,hout,0,NULL,NULL);
    uint32_t st[8]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    extern void sha256_block_data_order(uint32_t*, const uint8_t*, size_t);
    t0=now();
    sha256_block_data_order(st, bb, big/64);
    printf("cpu block 20MB: %.2f ms\n", (now()-t0)*1000);
    printf("gpu "); for(int i=0;i<8;i++) printf("%08x", hout[i]); printf("\n");
    printf("cpu "); for(int i=0;i<8;i++) printf("%08x", st[i]); printf("\n");
    return 0;
}
EOF
