#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include <dlfcn.h>

typedef void (*block_fn)(uint32_t*, const uint8_t*, size_t);
static double now(){struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return t.tv_sec+t.tv_nsec*1e-9;}

static block_fn load(const char *path){
    void *h = dlopen(path, RTLD_NOW);
    if(!h){ printf("dlopen %s failed %s\n", path, dlerror()); return NULL; }
    block_fn f = (block_fn)dlsym(h, "sha256_block_data_order");
    printf("loaded %s -> %p\n", path, (void*)f);
    return f;
}
int main(){
    size_t n=20*1024*1024; n=(n/64)*64;
    uint8_t *buf = aligned_alloc(64, n);
    memset(buf, 0x5a, n);
    const char *paths[] = {
        "/usr/local/lib/libcrypto.3.dylib",
        "/usr/local/Cellar/openssl@3/3.6.5/lib/libcrypto.3.dylib",
        "/usr/local/Cellar/openssl@3/3.6.4/lib/libcrypto.3.dylib",
        "/Library/Frameworks/Python.framework/Versions/3.11/lib/libcrypto.3.dylib",
        NULL
    };
    for(int i=0; paths[i]; i++){
        block_fn f = load(paths[i]);
        if(!f) continue;
        uint32_t st[8]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
        f(st, buf, 1);
        double t0=now();
        int reps=3;
        for(int r=0;r<reps;r++){
            st[0]=0x6a09e667;st[1]=0xbb67ae85;st[2]=0x3c6ef372;st[3]=0xa54ff53a;
            st[4]=0x510e527f;st[5]=0x9b05688c;st[6]=0x1f83d9ab;st[7]=0x5be0cd19;
            f(st, buf, n/64);
        }
        printf("  %.2f ms  %08x%08x\n", (now()-t0)/reps*1000, st[0], st[1]);
    }
    return 0;
}
EOF
