    double tsc_hz = (c1-c0)/sec;
    printf("elapsed %.4f s  tsc delta %llu  apparent tsc/core? %.2f GHz  x=%u\n",
           sec, (unsigned long long)(c1-c0), tsc_hz/1e9, x);

    // tighter: use rdtsc around a short spin and also mach absolute time
    c0 = rdtsc();
    clock_gettime(CLOCK_MONOTONIC_RAW, &t0);
    for (volatile int i = 0; i < 100000000; i++) {}
    c1 = rdtsc();
