#include <stdio.h>
#include <stdint.h>
#include <string.h>
#include <stdlib.h>
#include <openssl/sha.h>
extern void sha256_block_data_order(uint32_t *state, const uint8_t *data, size_t num);

static void bswap_state_to_bytes(uint32_t st[8], uint8_t out[32]){
    for(int i=0;i<8;i++){
        out[i*4]=st[i]>>24; out[i*4+1]=st[i]>>16; out[i*4+2]=st[i]>>8; out[i*4+3]=st[i];
    }
}

/* Build the padded block(s) that SHA-256 would append after `len` bytes,
   as if those bytes were already consumed, and the next data starts after padding.
   For len multiple of 64 and len>=64, padding is exactly one 64-byte block:
   0x80 || zeros || 64-bit bitlength. */
int main(){
    size_t n1 = 64*100; // chunk1
    size_t n2 = 64*50;
    uint8_t *m1 = calloc(1, n1);
    uint8_t *m2 = calloc(1, n2);
    for(size_t i=0;i<n1;i++) m1[i]=i*3+1;
    for(size_t i=0;i<n2;i++) m2[i]=i*7+9;

    // reference hash of m1||m2
    uint8_t *all = malloc(n1+n2);
    memcpy(all, m1, n1); memcpy(all+n1, m2, n2);
    uint8_t ref[32];
    SHA256(all, n1+n2, ref);

    // hash m1 to get state S1 (midstate, before padding)
    uint32_t s1[8]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    sha256_block_data_order(s1, m1, n1/64);

    // length-extension: start from S1, feed the padding block of m1, then m2, then final padding of (n1+pad+n2)
    // padding of m1 (length n1 bytes, multiple of 64): one block
    uint8_t pad[64]={0};
    pad[0]=0x80;
    uint64_t bits = n1*8;
    for(int i=0;i<8;i++) pad[63-i] = (bits>>(8*i)) & 0xff;

    uint32_t s = 0; // just continue
    uint32_t st[8]; memcpy(st, s1, 32);
    sha256_block_data_order(st, pad, 1);
    sha256_block_data_order(st, m2, n2/64);
    // final padding for total length = n1 + 64 + n2
    size_t total = n1 + 64 + n2;
    uint8_t pad2[64]={0};
    pad2[0]=0x80;
    bits = total*8;
    for(int i=0;i<8;i++) pad2[63-i]=(bits>>(8*i))&0xff;
    sha256_block_data_order(st, pad2, 1);
    uint8_t out[32]; bswap_state_to_bytes(st, out);

    printf("ref "); for(int i=0;i<32;i++) printf("%02x", ref[i]); printf("\n");
    printf("ext "); for(int i=0;i<32;i++) printf("%02x", out[i]); printf("\n");
    printf("match %d\n", memcmp(ref,out,32)==0);

    // Also: can we get hash(m1||m2) from hash(m1) and m2 WITHOUT midstate? 
    // hash(m1) is state after padding, not midstate. Let's see if they're related.
    uint8_t h1[32]; SHA256(m1, n1, h1);
    printf("hash(m1) "); for(int i=0;i<32;i++) printf("%02x", h1[i]); printf("\n");
    printf("midstate "); for(int i=0;i<8;i++) printf("%08x", s1[i]); printf("\n");
    return 0;
}
