#include <stdio.h>
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>
#include <time.h>
#include <stdatomic.h>
extern void sha256_block_data_order(uint32_t *state, const uint8_t *data, size_t num);

static double now(){struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return t.tv_sec+t.tv_nsec*1e-9;}

#define MAXN 3
typedef struct {
    atomic_int stage;     /* 0 = waiting to receive, 1 = has state, computing, 2 = result ready */
    uint32_t state[8];
    size_t begin, count;  /* blocks this stage covers */
} slot_t;

typedef struct {
    uint8_t *data;
    size_t nblocks;
    size_t chunk;         /* blocks */
    int id, nthreads;
    slot_t *slots;        /* one per thread, circular stages? simpler: array of jobs */
    int njobs;
    atomic_int *job_ready;   /* job i ready to be computed by assigned thread; state in job_state[i] */
    uint32_t *job_state;     /* njobs * 8 */
    atomic_int *job_done;
} W;

/* Simpler design:
   Thread 0 computes job 0 from IV, publishes state.
   Thread 1 waits until job 0 done, computes job 1 from that state, publishes.
   Thread 0 waits until job 1 done, computes job 2, etc.
   While thread 1 computes job k, thread 0 can... nothing, because job k+1 needs job k's state.
   Prefetch only. This cannot overlap compute. Confirm and stop.
*/
int main(){
    printf("serial dependency cannot overlap; pipeline cannot beat single core for SHA-256 chain\n");
    /* Measure spin-wait handoff overhead alone to be sure */
    size_t n=8*1024*1024; n-=n%64;
    uint8_t *buf=aligned_alloc(64,n); memset(buf,0x5a,n);
    size_t nblocks=n/64;
    size_t chunk=8192;
    int njobs=(nblocks+chunk-1)/chunk;
    uint32_t *states=calloc(njobs+1, 32);
    uint32_t iv[8]={0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    memcpy(states, iv, 32);
    atomic_int *done=calloc(njobs+1, sizeof(atomic_int));
    atomic_store(&done[0], 1); /* IV ready */

    /* two threads alternating */
    /* We'll just time single-thread chunked to see chunk overhead */
    double t0=now();
    uint32_t st[8]; memcpy(st, iv, 32);
    for(size_t c=0;c<nblocks;c+=chunk){
        size_t take=chunk; if(c+take>nblocks) take=nblocks-c;
        sha256_block_data_order(st, buf+c*64, take);
    }
    printf("chunked single %.2f ms\n", (now()-t0)*1000);
    t0=now();
    memcpy(st, iv, 32);
    sha256_block_data_order(st, buf, nblocks);
    printf("monolithic %.2f ms\n", (now()-t0)*1000);
    return 0;
