static int stop = 0;

static void hash_range(uint32_t st[8], const uint8_t *data, size_t len) {
    size_t nblocks = len / 64;
    size_t rem = len % 64;
    if (nblocks) sha256_block_data_order(st, data, nblocks);
    uint8_t last[128];
    memset(last, 0, sizeof(last));
    if (rem) memcpy(last, data + nblocks*64, rem);
    last[rem] = 0x80;
    uint64_t bits = (uint64_t)len * 8;
    size_t padblocks = (rem < 56) ? 1 : 2;
    uint8_t *lenp = last + padblocks*64 - 8;
    for (int i = 7; i >= 0; i--) { lenp[i] = (uint8_t)(bits & 0xff); bits >>= 8; }
    sha256_block_data_order(st, last, padblocks);
}

static void state_to_bytes(uint32_t st[8], uint8_t out[32]) {
    for (int i = 0; i < 8; i++) {
        out[i*4]   = (uint8_t)(st[i] >> 24);
        out[i*4+1] = (uint8_t)(st[i] >> 16);
        out[i*4+2] = (uint8_t)(st[i] >> 8);
        out[i*4+3] = (uint8_t)st[i];
    }
}

static void *worker(void *arg) {
    int id = (int)(intptr_t)arg;
    int seen = 0;
    for (;;) {
        pthread_mutex_lock(&mu);
        while (job_gen == seen && !stop) pthread_cond_wait(&cv, &mu);
        if (stop) { pthread_mutex_unlock(&mu); return NULL; }
        int gen = job_gen;
        const uint8_t *data = job_data + job_off[id];
        size_t len = job_len[id];
        uint32_t st[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
                          0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
        pthread_mutex_unlock(&mu);

        hash_range(st, data, len);

        pthread_mutex_lock(&mu);
        memcpy(job_state[id], st, 32);
        seen = gen;
        job_done++;
        pthread_cond_signal(&cv_done);
        pthread_mutex_unlock(&mu);
    }
}

static PyObject *init_workers(PyObject *self, PyObject *arg) {
    int n = (int)PyLong_AsLong(arg);
    if (n < 1 || n > MAXW) { PyErr_SetString(PyExc_ValueError, "n"); return NULL; }
    if (nworkers) Py_RETURN_NONE;
    nworkers = n;
    for (int i = 0; i < n; i++)
        pthread_create(&threads[i], NULL, worker, (void*)(intptr_t)i);
    Py_RETURN_NONE;
}

/* sha256_parallel(buf, n) -> list of digests of equal chunks. For timing only. */
static PyObject *sha256_parallel(PyObject *self, PyObject *arg) {
    Py_buffer view;
    if (PyObject_GetBuffer(arg, &view, PyBUF_SIMPLE) != 0) return NULL;
    if (!nworkers) { PyBuffer_Release(&view); PyErr_SetString(PyExc_RuntimeError, "init"); return NULL; }
    size_t len = (size_t)view.len;
    size_t chunk = len / nworkers;
    pthread_mutex_lock(&mu);
    job_data = (const uint8_t*)view.buf;
    for (int i = 0; i < nworkers; i++) {
        job_off[i] = i * chunk;
        job_len[i] = (i == nworkers-1) ? (len - i*chunk) : chunk;
    }
    job_done = 0;
    job_gen++;
    pthread_cond_broadcast(&cv);
    while (job_done < nworkers) pthread_cond_wait(&cv_done, &mu);
    pthread_mutex_unlock(&mu);

    PyObject *list = PyList_New(nworkers);
    for (int i = 0; i < nworkers; i++) {
        uint8_t out[32];
        state_to_bytes(job_state[i], out);
        PyList_SET_ITEM(list, i, PyBytes_FromStringAndSize((char*)out, 32));
    }
    PyBuffer_Release(&view);
    return list;
}

/* single fast sha256 */
static PyObject *sha256_one(PyObject *self, PyObject *arg) {
    Py_buffer view;
    if (PyObject_GetBuffer(arg, &view, PyBUF_SIMPLE) != 0) return NULL;
    uint32_t st[8] = {0x6a09e667,0xbb67ae85,0x3c6ef372,0xa54ff53a,
                      0x510e527f,0x9b05688c,0x1f83d9ab,0x5be0cd19};
    hash_range(st, (const uint8_t*)view.buf, (size_t)view.len);
    uint8_t out[32];
    state_to_bytes(st, out);
    PyBuffer_Release(&view);
    return PyBytes_FromStringAndSize((char*)out, 32);
}

static PyMethodDef methods[] = {
    {"init", init_workers, METH_O, NULL},
    {"parallel", sha256_parallel, METH_O, NULL},
    {"sha256", sha256_one, METH_O, NULL},
    {NULL, NULL, 0, NULL}
};
static struct PyModuleDef module = {PyModuleDef_HEAD_INIT, "parsha", NULL, -1, methods};
PyMODINIT_FUNC PyInit_parsha(void) { return PyModule_Create(&module); }
